package local.pitv;
import org.xmlpull.v1.*;import java.io.*;import java.text.*;import java.util.*;
final class XmlGuide {
 static final class TextPool extends LinkedHashMap<String,String>{TextPool(){super(128,.75f,true);}protected boolean removeEldestEntry(Map.Entry<String,String> entry){return size()>8192;}String text(String value){String found=get(value);if(found!=null)return found;put(value,value);return value;}}

 interface Zones {String zone(String channel);}
 static final class Programme {String channel,title="",description="";long start,stop;}
 static final ThreadLocal<Map<String,SimpleDateFormat>> formats=ThreadLocal.withInitial(HashMap::new);
 static long time(String s)throws Exception{return time(s,"UTC");}
 static long time(String s,String zone)throws Exception {String value=s.trim();boolean offset=value.matches(".*[+-][0-9]{4}$");String source=zone==null||zone.isEmpty()?"UTC":zone;String key=offset?"offset":source;Map<String,SimpleDateFormat> cache=formats.get();SimpleDateFormat fmt=cache.get(key);if(fmt==null){fmt=new SimpleDateFormat(offset?"yyyyMMddHHmmss Z":"yyyyMMddHHmmss",Locale.ROOT);fmt.setLenient(false);if(!offset)fmt.setTimeZone(TimeZone.getTimeZone(source));if(cache.size()>32)cache.clear();cache.put(key,fmt);}ParsePosition pos=new ParsePosition(0);Date result=fmt.parse(value,pos);if(result==null||pos.getIndex()!=value.length())throw new IOException("Invalid guide timestamp");return result.getTime();}
 static Map<String,List<Programme>> parse(String xml)throws Exception{return parse(new ByteArrayInputStream(xml.getBytes("UTF-8")),channel->"UTC");}
 static Map<String,List<Programme>> parse(InputStream stream,Zones zones)throws Exception {return parse(stream,zones,null);}
 static Map<String,List<Programme>> parse(InputStream stream,Zones zones,Set<String> wanted)throws Exception {XmlPullParserFactory f=XmlPullParserFactory.newInstance();XmlPullParser p=f.newPullParser();p.setInput(stream,null);Map<String,List<Programme>> result=new HashMap<>();Programme current=null;TextPool titles=new TextPool(),descriptions=new TextPool();long now=System.currentTimeMillis();for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.DOCDECL)throw new IOException("DOCTYPE unsupported");if(event==XmlPullParser.START_TAG){String name=p.getName();if(name.equals("programme")){current=new Programme();current.channel=p.getAttributeValue(null,"channel");if(wanted!=null&&!wanted.contains(current.channel)){current=null;continue;}try{String zone=zones.zone(current.channel);current.start=time(p.getAttributeValue(null,"start"),zone);current.stop=time(p.getAttributeValue(null,"stop"),zone);}catch(Exception e){current=null;}}else if(current!=null&&name.equals("title"))current.title=titles.text(p.nextText());else if(current!=null&&name.equals("desc")){String text=p.nextText();if(wanted!=null&&text.length()>800){int limit=800;if(Character.isHighSurrogate(text.charAt(limit-1)))limit--;text=text.substring(0,limit)+"…";}current.description=descriptions.text(text);}}else if(event==XmlPullParser.END_TAG&&p.getName().equals("programme")&&current!=null){if(current.channel!=null&&current.stop>now-24*3600000L&&current.start<now+(wanted==null?7:2)*24*3600000L){List<Programme> list=result.get(current.channel);if(list==null){list=new ArrayList<>();result.put(current.channel,list);}if(list.size()<500)list.add(current);}current=null;}}for(List<Programme> list:result.values())Collections.sort(list,(a,b)->Long.compare(a.start,b.start));return result;}
}
